pub fn longlong2str<'a>(
    ctx: &'a Ctx,
    a0: i64,
    a1: Val<'a, i8>,
    a2: print_format<'a>,
) -> Val<'a, i8> {
    // Transliterated from its machine code: returns or uses a value its C never sets.
    (a0, a1, a2).put_regs(ctx);
    asm_longlong2str(ctx);
    Ret::get(ctx)
}

